-- ----------------------------
-- Table structure for ai_chat_message
-- ----------------------------
DROP TABLE IF EXISTS `ai_chat_message`;
CREATE TABLE `ai_chat_message`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '消息ID',
  `session_id` bigint(20) NOT NULL COMMENT '所属会话ID',
  `role` enum('USER','ASSISTANT') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息角色（USER=用户提问 ASSISTANT=AI回答）',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '消息内容（AI 回答为 Markdown 格式）',
  `sources` json NULL COMMENT '引用来源列表 [{title, author, bookId}]，仅 ASSISTANT 消息有值',
  `tokens_used` int(11) NULL DEFAULT NULL COMMENT '本次调用消耗的 Token 数（可选统计）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '消息时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_session_id`(`session_id`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE,
  CONSTRAINT `fk_msg_session` FOREIGN KEY (`session_id`) REFERENCES `ai_chat_session` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 25 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI 对话消息表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of ai_chat_message
-- ----------------------------
INSERT INTO `ai_chat_message` VALUES (1, 1, 'USER', '你好', NULL, NULL, '2026-07-09 20:12:29');
INSERT INTO `ai_chat_message` VALUES (2, 1, 'ASSISTANT', '嘿，你好呀！👋 欢迎来到智能图书馆！我是你的 AI 助手\"书灵\"，很高兴为你服务！\n\n我可以帮你做这些事情：\n- 📚 **搜索图书** — 按关键词或分类找书\n- 🔍 **语义搜索** — 用自然语言描述你想看的书\n- 📖 **借阅图书** — 帮你借书\n- 🔙 **归还图书** — 帮你还书\n- ❤️ **收藏图书** — 把喜欢的书收藏起来\n- 📋 **查询借阅记录/收藏列表**\n\n有什么我可以帮你的吗？比如想找本书看看，或者查查你的借阅情况？😊', NULL, NULL, '2026-07-09 20:12:32');
INSERT INTO `ai_chat_message` VALUES (3, 1, 'USER', '搜索图书', NULL, NULL, '2026-07-09 20:12:39');
INSERT INTO `ai_chat_message` VALUES (4, 1, 'ASSISTANT', '目前图书馆里有 **1 本书**，信息如下：\n\n📖 **《123》** — 作者：123\n- **分类**：文学\n- **库存**：2 本（共 2 本）\n- **简介**：123\n\n不过看起来书名和作者信息比较简略，可能是测试数据哦～ 😅\n\n要不你告诉我：\n1. **想搜什么类型的书？**（比如小说、科技、历史、哲学……）\n2. **有没有想看的书名或作者？**\n\n我可以帮你更精准地搜索！或者你也可以试试用自然语言描述你想看的书，我用语义搜索帮你找～ 📚✨', NULL, NULL, '2026-07-09 20:12:43');
INSERT INTO `ai_chat_message` VALUES (5, 2, 'USER', '有java的书籍吗', NULL, NULL, '2026-07-09 20:21:53');
INSERT INTO `ai_chat_message` VALUES (6, 2, 'ASSISTANT', '当然有！我找到了两本Java相关的书籍，以下是详细介绍：\n\n---\n\n**1. 《Java核心技术（第12版）》**\n- 作者：Cay S. Horstmann\n- 类别：计算机\n- 简介：Java经典教材，涵盖Java语言基础、面向对象、集合、多线程等核心知识。\n- 馆藏情况：共10本，目前可借阅8本（库存充足）\n\n**2. 《深入理解Java虚拟机》**\n- 作者：周志明\n- 类别：计算机\n- 简介：详细讲解JVM运行机制、垃圾回收、类加载及性能调优。\n- 馆藏情况：共6本，目前可借阅6本（库存充足）\n\n---\n\n这两本书都很经典——《Java核心技术》适合入门和系统学习，而《深入理解Java虚拟机》则适合想要深入JVM底层的读者。你对哪本感兴趣？需要我查看更详细的介绍，或者帮你借阅吗？', NULL, NULL, '2026-07-09 20:21:57');
INSERT INTO `ai_chat_message` VALUES (7, 2, 'USER', '我借第一本', NULL, NULL, '2026-07-09 20:22:10');
INSERT INTO `ai_chat_message` VALUES (8, 2, 'ASSISTANT', '借阅成功！以下是你的借阅信息：\n\n- **书名**：《Java核心技术（第12版）》\n- **作者**：Cay S. Horstmann\n- **借阅日期**：今天\n- **应还日期**：2026年8月8日\n\n请在到期前归还。祝你阅读愉快，如果还有其他需要，随时找我！', NULL, NULL, '2026-07-09 20:22:17');
INSERT INTO `ai_chat_message` VALUES (9, 2, 'USER', '帮我收藏java虚拟机这本书', NULL, NULL, '2026-07-09 20:26:46');
INSERT INTO `ai_chat_message` VALUES (10, 2, 'ASSISTANT', '已成功收藏《深入理解Java虚拟机》（作者：周志明）！你可以在收藏列表中随时查看这本书。\n\n还有其他需要帮忙的吗？比如查看收藏列表或借阅这本书？', NULL, NULL, '2026-07-09 20:26:49');
INSERT INTO `ai_chat_message` VALUES (11, 2, 'USER', '我借了几本书', NULL, NULL, '2026-07-09 20:37:58');
INSERT INTO `ai_chat_message` VALUES (12, 2, 'ASSISTANT', '你目前借了 **1本书**，详情如下：\n\n- **《Java核心技术（第12版）》** —— 作者：Cay S. Horstmann\n  - 借阅日期：2026年7月9日\n  - 应还日期：2026年8月8日\n  - 当前状态：**借阅中**\n\n还有将近一个月的时间，按时归还就好。如果想续借或有其他问题，随时找我！', NULL, NULL, '2026-07-09 20:38:02');
INSERT INTO `ai_chat_message` VALUES (13, 2, 'USER', '帮我换了', NULL, NULL, '2026-07-09 20:38:08');
INSERT INTO `ai_chat_message` VALUES (14, 2, 'ASSISTANT', '你想归还的是哪本书呢？目前你只有一本借阅记录——《Java核心技术（第12版）》，是归还这本吗？', NULL, NULL, '2026-07-09 20:38:10');
INSERT INTO `ai_chat_message` VALUES (15, 2, 'USER', '是的', NULL, NULL, '2026-07-09 20:38:16');
INSERT INTO `ai_chat_message` VALUES (16, 2, 'ASSISTANT', '《Java核心技术（第12版）》已成功归还！欢迎随时再来借阅其他书籍。还有其他需要帮忙的吗？', NULL, NULL, '2026-07-09 20:38:19');
INSERT INTO `ai_chat_message` VALUES (17, 3, 'USER', '我是一个新学java 的人 能给我推荐几本书吗', NULL, NULL, '2026-07-10 10:19:58');
INSERT INTO `ai_chat_message` VALUES (18, 3, 'ASSISTANT', '好的，下面给你推荐几本适合 Java 初学者入门的书籍：\n\n---\n\n**1. 《Java核心技术（第12版）》—— Cay S. Horstmann**\n\n这是 Java 领域非常经典的入门教材，内容从 Java 语言基础讲起，涵盖面向对象编程、集合框架、多线程等核心知识。第12版更新了最新的 Java 特性，非常适合初学者系统学习。目前馆内还有 **8本** 库存，比较充裕。\n\n**2. 《深入理解Java虚拟机》—— 周志明**\n\n虽然这本书偏进阶一些，但如果你是真心想学好 Java，建议尽早了解 JVM（Java 虚拟机）的基本原理，比如内存管理、垃圾回收机制等。这本书讲解得非常透彻，很多 Java 开发者都把这本书当作\"必备读物\"。不过这本书更适合你先学完基础语法后再看。目前馆内还有 **6本** 库存。\n\n---\n\n另外，刚刚搜索时看到馆内还有一本 **《MySQL数据库从入门到精通》**，学习 Java 开发通常也离不开数据库操作，后续可以配合学习。\n\n**推荐入门路线：**\n- 先读 **《Java核心技术》**，打好基础和面向对象编程思维\n- 有了一定基础后再看 **《深入理解Java虚拟机》**，了解底层原理\n\n你想借阅哪本书呢？我可以帮你操作借阅，也可以先把它们收藏起来方便以后查找。', NULL, NULL, '2026-07-10 10:20:07');
INSERT INTO `ai_chat_message` VALUES (19, 3, 'USER', '我要借 第一本书 你帮我借一下', NULL, NULL, '2026-07-10 10:20:23');
INSERT INTO `ai_chat_message` VALUES (20, 3, 'ASSISTANT', '借阅成功！以下是借阅信息：\n\n- **书名**：《Java核心技术（第12版）》\n- **作者**：Cay S. Horstmann\n- **借阅编号**：4\n- **应还日期**：2026年8月9日\n\n请记得在到期日前归还哦。祝你学习 Java 顺利，加油！如果后续还需要其他帮助，比如查询借阅记录或续借，随时找我。', NULL, NULL, '2026-07-10 10:20:28');
INSERT INTO `ai_chat_message` VALUES (21, 4, 'USER', '我学习java  你给我推荐一下书籍', NULL, NULL, '2026-07-10 11:07:15');
INSERT INTO `ai_chat_message` VALUES (22, 4, 'ASSISTANT', '找到了两本Java相关的好书，另外我再看看知识库中是否有推荐的图书信息。\n\n根据搜索结果，我为你推荐以下两本Java学习书籍：\n\n---\n\n**1. 《Java核心技术（第12版）》—— Cay S. Horstmann**\n这是Java学习的经典入门教材，内容涵盖Java语言基础、面向对象编程、集合框架、多线程等核心知识。非常适合初学者系统性地打好Java基础。目前馆藏还有7本可借，库存充足。\n\n**2. 《深入理解Java虚拟机》—— 周志明**\n如果你想深入学习Java，这本是进阶必备。它详细讲解了JVM运行机制、垃圾回收、类加载及性能调优等内容。当你掌握了基础语法后，读这本书能让你对Java底层有深刻理解。目前有6本可借。\n\n---\n\n**我的建议学习路线：**\n如果你是Java初学者，建议先从 **《Java核心技术》** 入手，打好基础；等有一定编程经验后，再看 **《深入理解Java虚拟机》** 提升内功。\n\n你对哪本书感兴趣？需要我帮你查看详细内容，或者直接办理借阅吗？', NULL, NULL, '2026-07-10 11:07:20');
INSERT INTO `ai_chat_message` VALUES (23, 4, 'USER', '帮我借阅一下第一本书', NULL, NULL, '2026-07-10 11:07:31');
INSERT INTO `ai_chat_message` VALUES (24, 4, 'ASSISTANT', '借阅成功！以下是你的借阅信息：\n\n**书名：**《Java核心技术（第12版）》\n**作者：** Cay S. Horstmann\n**借阅编号：** 5\n**应还日期：** 2026年8月9日\n\n请你按时归还，祝你学习Java顺利！如果后续想借阅《深入理解Java虚拟机》，或者需要其他帮助，随时来找我。', NULL, NULL, '2026-07-10 11:07:35');

-- ----------------------------
-- Table structure for ai_chat_session
-- ----------------------------
DROP TABLE IF EXISTS `ai_chat_session`;
CREATE TABLE `ai_chat_session`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '会话ID',
  `user_id` bigint(20) NOT NULL COMMENT '所属用户ID',
  `title` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT '新对话' COMMENT '会话标题（首条消息自动截取）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '最后活跃时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_updated_at`(`updated_at`) USING BTREE,
  CONSTRAINT `fk_session_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 5 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI 对话会话表' ROW_FORMAT = Dynamic;

