-- ----------------------------
-- Table structure for ai_recommendation
-- ----------------------------
DROP TABLE IF EXISTS `ai_recommendation`;
CREATE TABLE `ai_recommendation`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '推荐记录ID',
  `user_id` bigint(20) NOT NULL COMMENT '被推荐用户ID',
  `book_id` bigint(20) NOT NULL COMMENT '推荐图书ID',
  `reason` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT 'AI 生成的推荐理由（Markdown 格式）',
  `score` decimal(4, 3) NULL DEFAULT NULL COMMENT '推荐相关度分数（0.000~1.000）',
  `source` enum('AI','HOT') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'AI' COMMENT '推荐来源（AI=模型推荐 HOT=热门降级）',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '推荐生成时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_book_id`(`book_id`) USING BTREE,
  INDEX `idx_created_at`(`created_at`) USING BTREE,
  CONSTRAINT `fk_rec_book` FOREIGN KEY (`book_id`) REFERENCES `book` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_rec_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 21 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI 推荐记录表' ROW_FORMAT = Dynamic;

