-- ----------------------------
-- Table structure for ai_tool_call_log
-- ----------------------------
DROP TABLE IF EXISTS `ai_tool_call_log`;
CREATE TABLE `ai_tool_call_log`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '主键',
  `session_id` bigint(20) NULL DEFAULT NULL COMMENT '会话ID',
  `user_id` bigint(20) NULL DEFAULT NULL COMMENT '用户ID',
  `tool_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL DEFAULT NULL COMMENT '工具名称',
  `tool_params` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '工具参数（JSON）',
  `tool_result` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '工具返回结果（JSON）',
  `execution_time` bigint(20) NULL DEFAULT NULL COMMENT '执行时长（毫秒）',
  `success` tinyint(1) NULL DEFAULT NULL COMMENT '是否成功（1成功/0失败）',
  `error_msg` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '错误信息',
  `create_time` datetime NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_session_id`(`session_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_tool_name`(`tool_name`) USING BTREE,
  INDEX `idx_create_time`(`create_time`) USING BTREE
) ENGINE = InnoDB AUTO_INCREMENT = 22 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = 'AI工具调用日志表' ROW_FORMAT = Dynamic;

