INSERT INTO `book` VALUES (33, 'ChatGPT应用开发指南', '赵磊', '9787302600042', '人工智能', '介绍大语言模型、Prompt工程、RAG知识库及AI应用开发。', '/uploads/covers/32.png', 10, 12, '2024-01-08', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (34, '红楼梦', '曹雪芹', '9787302600043', '文学', '中国古典四大名著之一，描绘贾、史、王、薛四大家族兴衰。', '/uploads/covers/33.png', 12, 15, '2016-05-01', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (35, '西游记', '吴承恩', '9787302600044', '文学', '中国古典神魔小说代表作，讲述唐僧师徒西天取经故事。', '/uploads/covers/34.png', 10, 12, '2017-02-14', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (36, '平凡的世界', '路遥', '9787302600045', '文学', '描绘普通人在时代变迁中的奋斗历程，激励无数读者。', '/uploads/covers/35.png', 8, 10, '2015-09-10', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (37, '资本论', '卡尔·马克思', '9787302600046', '经济', '政治经济学经典著作，系统分析资本主义经济运行规律。', '/uploads/covers/36.png', 4, 6, '2014-11-11', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (38, '枪炮、病菌与钢铁', '贾雷德·戴蒙德', '9787302600047', '历史', '探讨不同文明发展差异及历史演变的深层原因。', '/uploads/covers/37.png', 5, 7, '2018-08-08', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (39, '中国哲学简史', '冯友兰', '9787302600048', '哲学', '梳理中国哲学发展脉络，介绍儒家、道家等主要思想。', '/uploads/covers/38.png', 6, 8, '2019-12-20', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (40, '苏菲的世界', '乔斯坦·贾德', '9787302600049', '哲学', '通过小说形式介绍西方哲学发展史及主要哲学流派。', '/uploads/covers/39.png', 7, 9, '2020-06-16', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);
INSERT INTO `book` VALUES (41, '未来简史', '尤瓦尔·赫拉利', '9787302600050', '科学', '探讨人工智能、生物科技及未来社会的发展趋势。', '/uploads/covers/40.png', 9, 10, '2019-04-30', '2026-07-09 20:20:09', '2026-07-09 20:20:09', 0);

-- ----------------------------
-- Table structure for book_review
-- ----------------------------
DROP TABLE IF EXISTS `book_review`;
CREATE TABLE `book_review`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '评论ID',
  `user_id` bigint(20) NOT NULL COMMENT '评论用户ID',
  `book_id` bigint(20) NOT NULL COMMENT '图书ID',
  `rating` tinyint(4) NOT NULL COMMENT '评分（1-5星）',
  `content` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NULL COMMENT '评论内容',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '评论时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `deleted` tinyint(1) NOT NULL DEFAULT 0 COMMENT '逻辑删除',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_book_id`(`book_id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  CONSTRAINT `fk_review_book` FOREIGN KEY (`book_id`) REFERENCES `book` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_review_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 2 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '图书评论与评分表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of book_review
-- ----------------------------
INSERT INTO `book_review` VALUES (1, 1, 5, 5, '非常不错', '2026-07-10 10:12:41', '2026-07-10 10:12:41', 0);

-- ----------------------------
-- Table structure for borrow_record
-- ----------------------------
DROP TABLE IF EXISTS `borrow_record`;
CREATE TABLE `borrow_record`  (
  `id` bigint(20) NOT NULL AUTO_INCREMENT COMMENT '借阅记录ID',
  `user_id` bigint(20) NOT NULL COMMENT '借阅用户ID',
  `book_id` bigint(20) NOT NULL COMMENT '图书ID',
  `borrow_date` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '借阅时间',
  `due_date` datetime NOT NULL COMMENT '约定归还日期',
  `return_date` datetime NULL DEFAULT NULL COMMENT '实际归还日期（NULL 表示未归还）',
  `status` enum('BORROWED','RETURNED','OVERDUE') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL DEFAULT 'BORROWED' COMMENT '借阅状态',
  `created_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  INDEX `idx_user_id`(`user_id`) USING BTREE,
  INDEX `idx_book_id`(`book_id`) USING BTREE,
  INDEX `idx_status`(`status`) USING BTREE,
  INDEX `idx_due_date`(`due_date`) USING BTREE,
  CONSTRAINT `fk_borrow_book` FOREIGN KEY (`book_id`) REFERENCES `book` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT,
  CONSTRAINT `fk_borrow_user` FOREIGN KEY (`user_id`) REFERENCES `user` (`id`) ON DELETE RESTRICT ON UPDATE RESTRICT
) ENGINE = InnoDB AUTO_INCREMENT = 6 CHARACTER SET = utf8mb4 COLLATE = utf8mb4_general_ci COMMENT = '借阅记录表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of borrow_record
-- ----------------------------
